/* The i-th gift of `e`.  Everything reads gifts through this, so the
 * two-level indexing cannot be got wrong at a call site.
 *
 * Clamped, not asserted: a stale caller index must never turn into a wild
 * pointer read.  The first entry is a real item, so the fallback is a
 * harmless (if wrong) name rather than a crash. */
inline const Item& At(const Entry& e, int i) {
    if (i < 0) {
        i = 0;
    }
    const int at = static_cast<int>(e.first) + i;
    if (at < 0 || at >= kOrderCount) {
        return kItems[0];
    }
    const int item = static_cast<int>(kOrder[at]);
    if (item < 0 || item >= kItemCount) {
        return kItems[0];
    }
    return kItems[item];
}

/* Linear scan, once per hovered NPC. */
inline const Entry* Find(const char* en) {
    if (en == nullptr) {
        return nullptr;
    }
    for (int i = 0; i < kCount; ++i) {
        const char* a = kTable[i].en;
        const char* b = en;
        while (*a != 0 && *a == *b) {
            ++a;
            ++b;
        }
        if (*a == 0 && *b == 0) {
            return &kTable[i];
        }
    }
    return nullptr;
}

